    Key = X bsl N + Acc,
    case Key of
        8 -> d_field_Bucket_cumulative_count(Rest, 0, 0, 0, F@_1, F@_2, F@_3, F@_4, TrUserData);
        33 -> d_field_Bucket_cumulative_count_float(Rest, 0, 0, 0, F@_1, F@_2, F@_3, F@_4, TrUserData);
        17 -> d_field_Bucket_upper_bound(Rest, 0, 0, 0, F@_1, F@_2, F@_3, F@_4, TrUserData);
        26 -> d_field_Bucket_exemplar(Rest, 0, 0, 0, F@_1, F@_2, F@_3, F@_4, TrUserData);
        _ ->
            case Key band 7 of
                0 -> skip_varint_Bucket(Rest, 0, 0, Key bsr 3, F@_1, F@_2, F@_3, F@_4, TrUserData);
                1 -> skip_64_Bucket(Rest, 0, 0, Key bsr 3, F@_1, F@_2, F@_3, F@_4, TrUserData);
                2 -> skip_length_delimited_Bucket(Rest, 0, 0, Key bsr 3, F@_1, F@_2, F@_3, F@_4, TrUserData);
