dfp_read_field_def_BucketSpan(<<16, Rest/binary>>, Z1, Z2, F, F@_1, F@_2, TrUserData) -> d_field_BucketSpan_length(Rest, Z1, Z2, F, F@_1, F@_2, TrUserData);
