    Key = X bsl N + Acc,
    case Key of
        10 -> d_field_Exemplar_label(Rest, 0, 0, 0, F@_1, F@_2, F@_3, TrUserData);
        17 -> d_field_Exemplar_value(Rest, 0, 0, 0, F@_1, F@_2, F@_3, TrUserData);
        26 -> d_field_Exemplar_timestamp(Rest, 0, 0, 0, F@_1, F@_2, F@_3, TrUserData);
        _ ->
            case Key band 7 of
                0 -> skip_varint_Exemplar(Rest, 0, 0, Key bsr 3, F@_1, F@_2, F@_3, TrUserData);
                1 -> skip_64_Exemplar(Rest, 0, 0, Key bsr 3, F@_1, F@_2, F@_3, TrUserData);
                2 -> skip_length_delimited_Exemplar(Rest, 0, 0, Key bsr 3, F@_1, F@_2, F@_3, TrUserData);
