verify_msg(Msg) when tuple_size(Msg) >= 1 -> verify_msg(Msg, element(1, Msg), []);
verify_msg(X) -> mk_type_error(not_a_known_message, X, []).

verify_msg(Msg, MsgName) when is_atom(MsgName) -> verify_msg(Msg, MsgName, []);
verify_msg(Msg, Opts) when tuple_size(Msg) >= 1 -> verify_msg(Msg, element(1, Msg), Opts);
verify_msg(X, _Opts) -> mk_type_error(not_a_known_message, X, []).

verify_msg(Msg, MsgName, Opts) ->
    TrUserData = proplists:get_value(user_data, Opts),
    case MsgName of
        'LabelPair' -> v_msg_LabelPair(Msg, [MsgName], TrUserData);
        'Gauge' -> v_msg_Gauge(Msg, [MsgName], TrUserData);
        'Counter' -> v_msg_Counter(Msg, [MsgName], TrUserData);
        'Quantile' -> v_msg_Quantile(Msg, [MsgName], TrUserData);
        'Summary' -> v_msg_Summary(Msg, [MsgName], TrUserData);
        'Untyped' -> v_msg_Untyped(Msg, [MsgName], TrUserData);
        'Histogram' -> v_msg_Histogram(Msg, [MsgName], TrUserData);
        'Bucket' -> v_msg_Bucket(Msg, [MsgName], TrUserData);
        'BucketSpan' -> v_msg_BucketSpan(Msg, [MsgName], TrUserData);
        'Exemplar' -> v_msg_Exemplar(Msg, [MsgName], TrUserData);
        'Metric' -> v_msg_Metric(Msg, [MsgName], TrUserData);
        'MetricFamily' -> v_msg_MetricFamily(Msg, [MsgName], TrUserData);
        'Timestamp' -> v_msg_Timestamp(Msg, [MsgName], TrUserData);
        _ -> mk_type_error(not_a_known_message, Msg, [])
    end.


